      *3.0*L1(-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),2)
    +2.0*std::pow(za(j1,j5),2)*zb(j3,j4)/(std::pow(za(j1,j2),2)*zb(j1,j2)*za(j3,j4))
