    -std::pow(za(j1,j5),2)*zb(j1,j4)/(za(j2,j3)*za(j3,j4))
      *L0(-s(j2,j3),-s(j5,j1))/s(j5,j1)
    +std::pow(za(j1,j5),2)*zb(j1,j2)*za(j2,j5)/(za(j2,j3)*za(j3,j4)*za(j4,j5))
      *L0(-s(j2,j3),-s(j4,j5))/s(j4,j5)
